"""Build apps.yaml and roles.yaml by parsing the public guide text, not the generator catalog."""

import re
from pathlib import Path

import yaml

from meridian_dataset.access.recipe_tools import access_policy_markdown, catalog_text

HEADER_BUILT = (
    "# {what}\n"
    "# Fake data. Generated by `python -m meridian_access.policy build` from the public guide;\n"
    "# don't edit by hand.\n"
)
_BIRTHRIGHT = re.compile(r"^Birthright SSO apps, for every employee: (.+)\.$", re.M)
_CONTRACTOR = re.compile(r"^Contractors get the first \d+ of them: (.+)\.$", re.M)


def _ids(text: str) -> list[str]:
    return [part.strip() for part in text.split(",") if part.strip()]


def parse_policy_markdown(
    text: str,
) -> tuple[dict[str, list[str]], dict[str, dict[str, list[str]]]]:
    """Return (birthright, {role id: {sso_apps, other_apps}}) from the public policy text."""
    employee, contractor = _BIRTHRIGHT.search(text), _CONTRACTOR.search(text)
    if employee is None or contractor is None:
        raise ValueError("the public policy text has no birthright lines")
    birthright = {"employee": _ids(employee.group(1)), "contractor": _ids(contractor.group(1))}
    roles: dict[str, dict[str, list[str]]] = {}
    for line in text.splitlines():
        if not line.startswith("| ") or line.startswith(("| Role", "|---")):
            continue
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        if len(cells) != 3:
            raise ValueError(f"unexpected policy table row: {line!r}")
        roles[cells[0]] = {"sso_apps": _ids(cells[1]), "other_apps": _ids(cells[2])}
    return birthright, roles


def parse_catalog(text: str) -> tuple[list[dict[str, object]], dict[str, tuple[str, str]]]:
    """Return (apps in order, {role id: (title, department)}) from the public catalog text."""
    apps: list[dict[str, object]] = []
    roles: dict[str, tuple[str, str]] = {}
    section, department = "", ""
    for line in text.splitlines():
        if line.startswith("Departments, roles and sizes"):
            section = "roles"
        elif line.startswith("Apps (app id"):
            section = "apps"
        elif line and not line.startswith(" "):
            section = ""
        elif section == "roles" and line.startswith("    "):
            role_id, _, title = line.strip().partition(": ")
            roles[role_id] = (title, department)
        elif section == "roles" and line.startswith("  "):
            department = re.sub(r" \(\d+ people\)$", "", line.strip())
        elif section == "apps" and line.startswith("  "):
            app_id, kind, name = line.split(None, 2)
            apps.append({"id": app_id, "name": name, "sso": kind == "sso"})
    return apps, roles


def _dump(data: object) -> str:
    return yaml.safe_dump(data, sort_keys=False, allow_unicode=True, width=100)


def build_from_public() -> dict[str, str]:
    """{filename: yaml text} for apps.yaml and roles.yaml. Deterministic."""
    birthright, table = parse_policy_markdown(access_policy_markdown())
    apps, catalog_roles = parse_catalog(catalog_text())
    if set(table) != set(catalog_roles):
        raise ValueError("the policy table and the catalog disagree on the role list")
    roles = []
    for role_id, (title, department) in catalog_roles.items():
        roles.append({"id": role_id, "title": title, "department": department, **table[role_id]})
    return {
        "apps.yaml": HEADER_BUILT.format(what="Every app: id, display name, SSO or not.")
        + _dump({"apps": apps}),
        "roles.yaml": HEADER_BUILT.format(what="Birthright apps and each role's apps.")
        + _dump({"birthright": birthright, "roles": roles}),
    }


def check_files(directory: Path, expected: dict[str, str]) -> list[str]:
    """Names of files in `directory` that differ from `expected` (or are missing)."""
    return [
        name
        for name, text in expected.items()
        if not (directory / name).is_file() or (directory / name).read_text() != text
    ]
